package com.hau.notification.presentation.response;import com.hau.notification.domain.model.*;import java.time.Instant;import java.util.UUID;public record NotificationResponse(UUID id,NotificationType type,String title,String content,String referenceId,String referenceType,boolean read,Instant readAt,Instant createdAt){public static NotificationResponse from(Notification n){return new NotificationResponse(n.getId(),n.getType(),n.getTitle(),n.getContent(),n.getReferenceId(),n.getReferenceType(),n.isRead(),n.getReadAt(),n.getCreatedAt());}}
